//! Native hyperlink stringifiers use the internal href getter.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area href=initial><a id=anchor href=initial>Link</a><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://hyperlink-string.test/path/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn hyperlink_stringifier_canonical_area_and_anchor_descriptors_and_call(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var nodes=[document.getElementById('area'),document.getElementById('anchor')],types=[HTMLAreaElement,HTMLAnchorElement];for(var i=0;i<2;i++){var x=nodes[i],a=Object.getOwnPropertyDescriptor(types[i].prototype,'toString');if(!a||!a.enumerable||!a.configurable||!a.writable||typeof a.value!=='function'||a.value.length!==0||a.value.name!=='toString'||a.value!==x.toString||Object.hasOwn(x,'toString')||a.value.call(x)!=='https://hyperlink-string.test/path/initial'||String(x)!==x.href||''+x!==x.href)throw 'canonical hyperlink stringifier';var caught=false;try{new a.value();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'nonconstructible stringifier';if(Object.prototype.toString.call(x)!=='[object '+types[i].name+']')throw 'Object tag remains ordinary';}"#);}
#[test]
fn hyperlink_stringifier_uses_internal_href_not_author_getter_and_retains_protocol_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('area'),document.getElementById('anchor')]){var method=x.toString,calls=0;Object.defineProperty(x,'href',{configurable:true,get:function(){calls++;throw 'author href getter';}});if(method.call(x)!=='https://hyperlink-string.test/path/initial'||String(x)!=='https://hyperlink-string.test/path/initial'||calls)throw 'internal getter authority';x.toString=function(){return 'author';};if(String(x)!=='author'||method.call(x)!=='https://hyperlink-string.test/path/initial')throw 'ordinary method shadow';delete x.toString;Object.defineProperty(x,Symbol.toPrimitive,{configurable:true,value:function(hint){return hint+' author';}});if(String(x)!=='string author')throw 'ordinary primitive override';delete x[Symbol.toPrimitive];delete x.href;if(String(x)!==x.href)throw 'restored canonical stringifier';}"#);}
#[test]
fn hyperlink_stringifier_inert_raw_aliases_current_owner_base_and_separate_brands(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument(''),base=owner.createElement('base');base.setAttribute('href','https://first.test/path/');owner.head.appendChild(base);for(var name of ['area','a']){var x=owner.createElement(name);if(String(x)!=='')throw 'missing href';x.setAttribute('href','leaf');var attr=x.getAttributeNode('href');if(String(x)!=='https://first.test/path/leaf')throw 'inert base';base.setAttribute('href','https://second.test/current/');if(String(x)!=='https://second.test/current/leaf')throw 'live base';attr.value='https://example.test/\udfff';if(String(x)!=='https://example.test/%EF%BF%BD'||attr.value!=='https://example.test/\udfff')throw 'raw Attr USV projection';var clone=x.cloneNode(false);if(String(clone)!==String(x))throw 'independent clone';var caught=false,wrong=name==='area'?HTMLAnchorElement.prototype.toString:HTMLAreaElement.prototype.toString;try{wrong.call(x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'separate native brands';base.setAttribute('href','https://first.test/path/');}"#);}

#[test]
fn hyperlink_stringifier_brands_precede_ignored_argument_conversion(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var nodes=[document.getElementById('area'),document.getElementById('anchor')],types=[HTMLAreaElement,HTMLAnchorElement],calls=0,arg={toString:function(){calls++;throw 'ignored';}};for(var i=0;i<2;i++){var x=nodes[i],method=types[i].prototype.toString;for(var bad of [{},Object.create(types[i].prototype),document.body,nodes[1-i],document.createElementNS('urn:foreign',i?'a':'area')]){var caught=false;try{method.call(bad,arg);}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'genuine stringifier brand and ignored arguments';}if(method.call(x,arg)!==x.href||calls)throw 'extra argument ignored';}"#);
}
#[test]
fn hyperlink_stringifier_reads_pay_work_copy_string_deadline_and_recover(){
 for name in ["area","a"]{for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let code=if inert{format!("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','{name}');x.href='https://example.test/path';")}else{format!("var x=document.getElementById('{}');",if name=="area"{"area"}else{"anchor"})};run(&mut d,&mut f,&mut p,&code);let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("hyperlink handle")};let method=if name=="area"{script_hyperlink_stringifier::AREA}else{script_hyperlink_stringifier::ANCHOR};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hyperlink_stringify(object,method);if mode==4{assert!(matches!(result,Ok(Value::String(_))));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("time"),"{name}/{inert}/{mode}: {e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hyperlink_stringify(object,method).is_ok());}}}
}
#[test]
fn hyperlink_stringifier_saved_child_origin_authority_and_fresh_recovery(){
 for (id,interface) in [("area","HTMLAreaElement"),("anchor","HTMLAnchorElement")]{let(mut d,mut f,mut p)=fixture();let code=format!("var x=document.getElementById('{id}'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.{interface}.prototype.toString;if(method.call(x)!==x.href)throw 'captured stringifier';");run(&mut d,&mut f,&mut p,&code);p.set_location(&crate::navigation::address("https://other-string.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("method.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://hyperlink-string.test/path/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(method.call(x)!=='https://hyperlink-string.test/path/initial')throw 'fresh origin stringifier recovery';");}
}
#[test]
fn hyperlink_stringifier_saved_identity_global_and_prototype_deletion(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var pair of [[document.getElementById('area'),HTMLAreaElement,'HTMLAreaElement'],[document.getElementById('anchor'),HTMLAnchorElement,'HTMLAnchorElement']]){var x=pair[0],C=pair[1],name=pair[2],P=C.prototype,method=P.toString,d=Object.getOwnPropertyDescriptor(P,'toString');var calls=0;x.valueOf=function(){calls++;return 7;};if(''+x!=='7'||calls!==1||String(x)!==method.call(x))throw 'ordinary valueOf precedence';delete x.valueOf;delete window[name];if(!(x instanceof C)||method.call(x)!==x.href||String(x)!==x.href)throw 'saved interface stringifier';delete P.toString;if(x.toString!==Object.prototype.toString||String(x)!=='[object '+name+']'||method.call(x)!==x.href)throw 'ordinary prototype method deletion';Object.defineProperty(P,'toString',d);if(P.toString!==method||String(x)!==x.href)throw 'restored canonical method';}"#);
}
